CREATE TABLE IF NOT EXISTS team_invites(id INT PRIMARY KEY AUTO_INCREMENT,store_id INT NOT NULL,email VARCHAR(190) NOT NULL,name VARCHAR(80) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,created_by INT NOT NULL,status ENUM('pending','accepted','revoked') NOT NULL DEFAULT 'pending',expires_at DATETIME NOT NULL,accepted_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(store_id,status));
CREATE TABLE IF NOT EXISTS account_recovery(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,created_by INT NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id));
CREATE TABLE IF NOT EXISTS notifications(id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,title VARCHAR(160) NOT NULL,body VARCHAR(1000) NOT NULL,link VARCHAR(200) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT 0,event_key VARCHAR(190) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(user_id,event_key),INDEX(user_id,is_read,created_at));
